//! Xiaomi model catalog ported from Pi's `packages/ai/src/providers/xiaomi.models.ts`.
//!
//! Pi marks this catalog as generated by `scripts/generate-models.ts`; this Rust port
//! preserves the generated entries as checked in for this port row.

/// Pricing metadata for a Xiaomi model.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct XiaomiModelCost {
    /// Input token price in Pi's model catalog units.
    pub input: f64,
    /// Output token price in Pi's model catalog units.
    pub output: f64,
    /// Cache-read token price in Pi's model catalog units.
    pub cache_read: f64,
    /// Cache-write token price in Pi's model catalog units.
    pub cache_write: f64,
}

/// OpenAI-compatible behavior overrides for a Xiaomi model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct XiaomiModelCompat {
    /// Whether replayed assistant messages require reasoning content.
    pub requires_reasoning_content_on_assistant_messages: bool,
    /// Pi thinking payload format identifier.
    pub thinking_format: &'static str,
}

/// One Xiaomi model entry from Pi's generated model catalog.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct XiaomiModel {
    /// Model id and catalog key.
    pub id: &'static str,
    /// Human-readable model name.
    pub name: &'static str,
    /// API implementation id.
    pub api: &'static str,
    /// Provider id.
    pub provider: &'static str,
    /// Base API URL.
    pub base_url: &'static str,
    /// Compatibility flags.
    pub compat: XiaomiModelCompat,
    /// Whether the model supports reasoning.
    pub reasoning: bool,
    /// Supported input modalities.
    pub input: &'static [&'static str],
    /// Model cost metadata.
    pub cost: XiaomiModelCost,
    /// Context window in tokens.
    pub context_window: u32,
    /// Maximum output tokens.
    pub max_tokens: u32,
}

const TEXT: &[&str] = &["text"];
const TEXT_IMAGE: &[&str] = &["text", "image"];
const API: &str = "openai-completions";
const PROVIDER: &str = "xiaomi";
const BASE_URL: &str = "https://api.xiaomimimo.com/v1";
const COMPAT: XiaomiModelCompat = XiaomiModelCompat {
    requires_reasoning_content_on_assistant_messages: true,
    thinking_format: "deepseek",
};

