#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preserves_xiaomi_catalog_metadata() {
        assert_eq!(XIAOMI_MODELS.len(), 6);
        assert_eq!(XIAOMI_MODELS[0].id, "mimo-v2-flash");
        assert_eq!(XIAOMI_MODELS[0].max_tokens, 65_536);
        assert_eq!(XIAOMI_MODELS[1].input, TEXT_IMAGE);
        assert_eq!(XIAOMI_MODELS[2].cost.input, 0.435);
        assert_eq!(XIAOMI_MODELS[3].context_window, 1_048_576);
        assert_eq!(XIAOMI_MODELS[5].cost.output, 2.61);
        assert_eq!(XIAOMI_MODELS[5].compat, COMPAT);
    }
}
